// Allow-list pengirim + bersihkan isi email → payload capture.
// Input = Gmail Trigger simple=false (mailparser, sama dengan IMAP "resolved"): id (Gmail), from.value[0].address,
// subject, text, html, textAsHtml, messageId, headers{key: "Key: value"}. Email dibaca dari trigger, bukan dari
// $input (node sebelumnya hanya daftar label Gmail).
const allowed = String($env.SB_EMAIL_ALLOWED_SENDERS || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const stripHtml = (h) => String(h || '')
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
  .replace(/<br\s*\/?>|<\/(p|div|li|tr|h[1-6])>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
  .replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n');
// ID label penanda (buat dulu di Gmail); tidak ada → node Tambah label dilewati.
const labelName = String($env.SB_GMAIL_PROCESSED_LABEL || 'SecondBrain/Processed').trim();
const label = $('Daftar label Gmail').all().map(l => l.json).find(l => l.name === labelName);
const out = [];
for (const i of $('Email masuk (Gmail)').all()) {
  const e = i.json;
  const fromRaw = String(e.from?.value?.[0]?.address ?? e.from?.text ?? e.from ?? '').toLowerCase();
  const from = (fromRaw.match(/[^\s<>"]+@[^\s<>"]+/) || [''])[0];
  if (!from || !allowed.includes(from)) continue; // fail-closed
  const subject = String(e.subject || '(tanpa subjek)').trim();
  // Subjek "task: ..." → tugas, "note: ..." → catatan, selain itu → inbox
  const m = subject.match(/^\s*(task|tugas|note|catatan)\s*:\s*(.*)$/i);
  const target = m ? (/^(task|tugas)$/i.test(m[1]) ? 'task' : 'note') : 'inbox';
  // text kosong (email HTML-only) → fallback ke html/textAsHtml yang di-strip
  const rawText = String(e.text || e.textPlain || '').trim() || stripHtml(typeof e.html === 'string' ? e.html : e.textAsHtml);
  const body = rawText.replace(/\r/g, '').split(/\n-- \n|\nOn .+wrote:\n/)[0].trim();
  // headers (resolved) berisi baris penuh "Message-ID: <...>" → buang prefiks nama header
  const hdrId = String(e.headers?.['message-id'] || '').replace(/^message-id:\s*/i, '').trim();
  const msgId = String(e.messageId || hdrId || '').trim();
  out.push({ json: { payload: {
    user_email: from,
    source: 'email',
    target,
    title: (m ? m[2] : subject).slice(0, 300),
    text: body.slice(0, 20000),
    summarize: body.length > 1500,  // minta server membuat ai_summary untuk email panjang
    external_id: msgId ? `email:${msgId}`.slice(0, 500) : null,
  }, gmail_id: e.id, label_id: label?.id ?? null } });
}
return out;
